using MusicGen.Core.Layers;
using MusicGen.Core.Testing;
using HeartMuLa.Model;
using TorchSharp;
using Xunit.Abstractions;
using static TorchSharp.torch;

namespace HeartMuLa.Tests;

/// <summary>
/// torchtune's RoPE (Llama3ScaledRoPE) against rope.safetensors, generated by tools/dump_reference.py with
/// dim=128, base=500000, max_seq_len=8192, scale_factor=32 (the params of the fixture itself). Needs no checkpoint.
/// </summary>
public class RopeParityTests
{
    private readonly Dictionary<string, Tensor> _fx = Fixtures.Load("rope.safetensors");
    private readonly ITestOutputHelper _out;

    public RopeParityTests(ITestOutputHelper output) => _out = output;

    private RotaryEmbedding Rope()
    {
        var p = _fx["params"].data<float>().ToArray(); // dim, base, max_seq, scale_factor, low, high, old_ctx
        return new RotaryEmbedding(RopeLayout.AdjacentPairs, RopeFrequencies.Llama3Scaled(p[1], p[3]), RopeTable.Float32Cached, (int)p[0], (int)p[2]);
    }

    private static float MaxAbs(Tensor got, Tensor expected) => (got.to(ScalarType.Float32) - expected.to(ScalarType.Float32)).abs().max().item<float>();

    [Fact]
    public void F32_LowAndFarPositions_MatchTorchtune()
    {
        var rope = Rope();
        var x = _fx["x"];

        var small = MaxAbs(rope.Apply(x, _fx["pos_small"], 1), _fx["out_small"]);
        var large = MaxAbs(rope.Apply(x, _fx["pos_large"], 1), _fx["out_large"]);

        _out.WriteLine($"F32 max_abs: pos 0..15 = {small:E3}, pos 4000..4015 = {large:E3}");
        Assert.True(small <= 1e-4f, $"positions 0..15: max_abs {small:E3}");
        Assert.True(large <= 1e-4f, $"positions 4000..4015: max_abs {large:E3}");
        Assert.True(MaxAbs(_fx["out_small"], _fx["out_large"]) > 1e-2f, "the fixture does not tell low positions from far ones");
    }

    // Ordered key of a bf16 (sign-magnitude bits → ordered integer): the distance between keys is the distance in ulps.
    private static int OrderedKey(ushort bits) => (bits & 0x8000) != 0 ? (~bits & 0xFFFF) : (bits | 0x8000);

    [Fact]
    public void Bf16_MatchesTorchtuneWithin1Ulp()
    {
        var rope = Rope();
        var got = rope.Apply(_fx["x_bf16"], _fx["pos_small"], 1);
        Assert.Equal(ScalarType.BFloat16, got.dtype);

        var g = System.Runtime.InteropServices.MemoryMarshal.Cast<byte, ushort>(got.contiguous().bytes).ToArray();
        var e = System.Runtime.InteropServices.MemoryMarshal.Cast<byte, ushort>(_fx["out_bf16"].contiguous().bytes).ToArray();
        Assert.Equal(e.Length, g.Length);

        int worst = 0, over = 0;
        for (int i = 0; i < g.Length; i++)
        {
            int d = Math.Abs(OrderedKey(g[i]) - OrderedKey(e[i]));
            worst = Math.Max(worst, d);
            if (d > 1) over++;
        }
        _out.WriteLine($"bf16: {g.Length} values, worst difference {worst} ulp, {over} above 1 ulp");
        Assert.True(over == 0, $"{over} of {g.Length} values differ by more than 1 ulp (worst: {worst} ulp)");
    }
}
